function assignRiskData(p: typeof raw_projects[0]): Project {
  const ac = p.anomaly_confidence ?? 0;
  let riskScore: number;
  let riskLevel: RiskLevel;

  if (p.anomaly_type === 'Progress Mismatch') {
    riskScore = Math.min(100, Math.round(ac * 0.95 + 4));
  } else if (p.anomaly_type === 'High Cost') {
    riskScore = Math.min(100, Math.round(ac * 0.90 + 5));
  } else if (p.anomaly_type === 'Delayed Completion' || p.anomaly_type === 'Contractor Pattern') {
    riskScore = Math.min(100, Math.round(ac * 0.75 + 5));
  } else {
    riskScore = Math.max(5, Math.round(ac * 0.3 + 5));
  }

  if (riskScore >= 81) riskLevel = 'CRITICAL';
  else if (riskScore >= 61) riskLevel = 'HIGH';
  else if (riskScore >= 31) riskLevel = 'MEDIUM';
  else riskLevel = 'LOW';

  const fundUtil = p.fund_released > 0 ? (p.expenditure / p.fund_released) * 100 : 0;
  const progressGap = Math.max(0, fundUtil - p.physical_progress);
  const today = new Date();
  const expDate = new Date(p.expected_completion_date);
  const delayDays = p.work_status !== 'Completed' ? Math.max(0, Math.round((today.getTime() - expDate.getTime()) / 86400000)) : 0;
  const sectorAvg = p.recommended_cost * 0.75;
  const costDevPct = ((p.recommended_cost - sectorAvg) / sectorAvg) * 100;

  const riskFactors = [
    {
      name: 'Expenditure vs Progress',
      contribution: Math.min(100, Math.round(progressGap * 2)),
      value: `${fundUtil.toFixed(0)}% funds, ${p.physical_progress}% physical`,
      expected: 'Gap < 10%',
    },
    {
      name: 'Cost Deviation',
      contribution: Math.min(100, Math.round(Math.abs(costDevPct) * 0.8)),
      value: `₹${p.recommended_cost}L`,
      expected: `₹${sectorAvg.toFixed(0)}L (sector avg)`,
    },
    {
      name: 'Completion Delay',
      contribution: Math.min(100, Math.round(delayDays / 3)),
      value: delayDays > 0 ? `${delayDays} days overdue` : 'On schedule',
      expected: 'On schedule',
    },
    {
      name: 'Payment Frequency',
      contribution: Math.min(100, Math.round(p.payment_count * 4)),
      value: `${p.payment_count} payments`,
      expected: '4-6 expected',
    },
  ].sort((a, b) => b.contribution - a.contribution);

  return {
    ...p,
    risk_score: riskScore,
    risk_level: riskLevel,
    risk_factors: riskFactors,
    cost_deviation_pct: parseFloat(costDevPct.toFixed(1)),
    progress_expenditure_gap: parseFloat(progressGap.toFixed(1)),
    delay_days: delayDays,
    similar_project_avg_cost: parseFloat(sectorAvg.toFixed(0)),
  };
}

export const PROJECTS: Project[] = raw_projects.map(assignRiskData);

